// ───────────────────────── Recorrido ─────────────────────────
const args = Bun.argv.slice(2);
const [iso, id] = args;
if (!iso || !id) { console.error("Uso: bun src/cli/coverage.ts <iso> <ID> [--docs]"); process.exit(1); }
const disc = await GameDisc.open(iso);
disc.resolveNames(await loadCandidates(disc, embedded.filenameLists));

interface Item { key: string; cat: Cat; status: Status; was: Status; bytes: number; files: Set<string>; label: string; tag: string; es: string; en: string; reader?: string; chunk?: number; count: number }
const items = new Map<string, Item>();
const add = (key: string, base: Omit<Item, "bytes" | "files" | "count">, bytes: number, file: string, n = 1) => {
  let it = items.get(key);
  if (!it) { it = { ...base, bytes: 0, files: new Set(), count: 0 }; items.set(key, it); }
  it.bytes += bytes; it.files.add(file); it.count += n;
};
const fin = (r: Rule, fileUsed: boolean) => (r.status === "decoded" && r.used && fileUsed ? "used" : r.status === "used" && !fileUsed ? "decoded" : r.status) as Status;
const finWas = (r: Rule, fileUsed: boolean) => { const s = r.was ?? r.status; return (s === "decoded" && r.used && fileUsed ? "used" : s === "used" && !fileUsed ? "decoded" : s) as Status; };

const seen = new Set<string>();
let dupBytes = 0, dupCount = 0;
const unknownChunkIds = new Map<number, number>();
for (const e of disc.entries) {
  const loc = `${e.archive}:${e.localSector}`;
  const path = disc.displayName(e);
  if (seen.has(loc) && e.size) { dupBytes += e.size; dupCount++; continue; }
  seen.add(loc);
  if (!e.size) continue;
  const fr = FILE_RULES.find(r => r.re.test(path));
  if (!fr) throw new Error(`Sin regla: ${path}`);
  const fileUsed = fr.used ?? fr.status === "used";
  if (fr.abk) {
    const h = await disc.readEntry(e, 0, 0x30);
    const dv = new DataView(h.buffer, h.byteOffset);
    const mod = Math.max(0, dv.getUint32(0x18, true) - dv.getUint32(0x1c, true));
    add("abk-modules", { key: "abk-modules", cat: "audio", status: "partial", was: "partial", label: "SOUND\\**\\*.ABK · módulos AEMS / AEMS modules", tag: "[V][D]",
      es: "Código MIPS del EE que elige la muestra según los parámetros. No se ejecuta: el port usa la lógica de la decomp.",
      en: "EE MIPS code that picks the sample from the parameters. Not executed: the port uses the decomp's logic.", reader: "lib/abk.ts (solo tamaño)" }, mod, path);
    add(fr.label, { key: fr.label, cat: fr.cat, status: fin(fr, true), was: finWas(fr, true), label: fr.label, tag: fr.tag, es: fr.es, en: fr.en, reader: fr.reader }, e.size - mod, path);
    continue;
  }
  if (!fr.chunked) {
    add(fr.label, { key: fr.label, cat: fr.cat, status: fr.status, was: fr.was ?? fr.status, label: fr.label, tag: fr.tag, es: fr.es, en: fr.en, reader: fr.reader }, e.size, path);
    continue;
  }
  let buf = await disc.readEntry(e);
  const magic = String.fromCharCode(...buf.subarray(0, 4));
  if (["JDLZ", "HUFF", "RAWW"].includes(magic)) buf = lzDecompress(buf);
  let leaves: [number, number][] = [];
  try { leaves = [...walk(parseChunks(buf))].filter(([c]) => !c.children).map(([c]) => [c.id, c.size + 8]); }
  catch { leaves = [[-1, buf.length]]; }
  const total = buf.length, scale = e.size / total;
  let counted = 0;
  for (const [cid, b] of leaves) {
    counted += b;
    const r = CHUNK_RULES[cid];
    const cat = (fr.cat === "unused" ? "unused" : r?.cat ?? fr.cat) as Cat; // un archivo sin uso no reparte sus chunks
    if (!r) {
      unknownChunkIds.set(cid, (unknownChunkIds.get(cid) ?? 0) + b * scale);
      add(`chunk:${cid}`, { key: `chunk:${cid}`, cat, status: "unknown", was: "unknown", label: cid < 0 ? "no es bChunk" : `0x${hex8(cid)}`, tag: "[H]", es: "Sin nombre en la decomp.", en: "No name in the decomp.", chunk: cid }, b * scale, path);
      continue;
    }
    // Chunks de un archivo sin usar: nunca «usado»
    const st = fin(r, fileUsed), was = finWas(r, fileUsed);
    const key = `chunk:${cid}:${cat}:${st}`;
    add(key, { key, cat, status: st, was, label: `0x${hex8(cid)} ${r.name}`, tag: r.tag, es: r.es, en: r.en, reader: r.reader, chunk: cid }, b * scale, path);
  }
  // Cabeceras de contenedores y cola: estructura bChunk (descifrada)
  const rest = (total - counted) * scale;
  if (rest > 0) add(`bchunk-struct:${fr.cat}:${fileUsed}`, { key: "", cat: fr.cat, status: fileUsed ? "used" : "decoded", was: fileUsed ? "used" : "decoded", label: "cabeceras bChunk / bChunk headers", tag: "[V]",
    es: "Cabeceras de contenedores y compresión.", en: "Container headers and compression.", reader: "lib/bchunk.ts" }, rest, path);
}

// Archivos del ISO fuera de ZDIR
const isoFiles = disc.files.filter(f => !f.isDir);
for (const f of isoFiles) {
  if (/ZZDATA\d\.BIN$/i.test(f.path)) continue;
  if (/^SLES_|^SLUS_|^SCES_|^SCUS_/i.test(f.path)) add("elf", { key: "elf", cat: "system", status: "decoded", was: "decoded", label: f.path, tag: "[D]", es: "Ejecutable del juego (la decomp coincide con el de la NTSC-U; doc 01).", en: "Game executable (the decomp matches the NTSC-U one; doc 01).", reader: "experiments/decomp" }, f.size, f.path);
  else if (/ZDIR\.BIN$/i.test(f.path)) add("zdir", { key: "zdir", cat: "system", status: "used", was: "used", label: f.path, tag: "[V]", es: "Índice de archivos.", en: "File index.", reader: "lib/zdir.ts" }, f.size, f.path);
  else if (/SYSTEM\.CNF$/i.test(f.path)) add("cnf", { key: "cnf", cat: "system", status: "used", was: "used", label: f.path, tag: "[V]", es: "Arranque (identifica el disco).", en: "Boot config (identifies the disc).", reader: "cli/build-all.ts" }, f.size, f.path);
  else add("irx", { key: "irx", cat: "system", status: "decoded", was: "unknown", label: "NFS/IOPRP*.IMG, NFS/IRX*.BUN", tag: "[V]", reader: "identificados por sus cadenas",
    es: "Módulos ELF del IOP: IOPRP280.IMG = imagen ROMDIR de Sony (16 módulos, cdvdfsv…); IRX281A = SIO2MAN, PADMAN, MCMAN, MCSERV; IRX281B = LIBSD, SDRDRV, SNDDRV (sonido de EA), USBD, LGDEV (volante Logitech). Un port no los necesita.",
    en: "IOP ELF modules: IOPRP280.IMG = Sony ROMDIR image (16 modules, cdvdfsv…); IRX281A = SIO2MAN, PADMAN, MCMAN, MCSERV; IRX281B = LIBSD, SDRDRV, SNDDRV (EA sound), USBD, LGDEV (Logitech wheel). Not needed by a port." }, f.size, f.path);
}
// Huecos de ZZDATA no referenciados por ZDIR
let gap = 0;
for (let a = 0; a < disc.archives.length; a++) {
  const used = disc.entries.filter(e => e.archive === a).map(e => [e.localSector * 2048, e.localSector * 2048 + e.size] as [number, number]).sort((x, y) => x[0] - y[0]);
  let end = 0, cov = 0;
  for (const [s, t] of used) { if (t <= end) continue; cov += t - Math.max(s, end); end = t; }
  gap += disc.archives[a].size - cov;
}
add("gaps", { key: "gaps", cat: "system", status: "decoded", was: "decoded", label: "ZZDATA: relleno entre archivos", tag: "[V]", es: "Alineación a sector y huecos sin archivo.", en: "Sector alignment and unreferenced gaps." }, gap, "NFS/ZZDATA*.BIN");

// ───────────────────────── Informe ─────────────────────────
const all = [...items.values()];
const total = all.reduce((s, i) => s + i.bytes, 0);
const sum = (f: (i: Item) => boolean, k: "status" | "was" = "status") => all.filter(f).reduce((s, i) => s + i.bytes, 0);
const by = (k: "status" | "was") => Object.fromEntries((Object.keys(ST) as Status[]).map(s => [s, sum(i => i[k] === s)])) as Record<Status, number>;
const now = by("status"), before = by("was");
const pct = (n: number, d = total) => `${(100 * n / d).toFixed(2)} %`;
const mb = (n: number) => (n / 1048576).toFixed(n < 1048576 ? 3 : 1);
const understood = (r: Record<Status, number>) => r.used + r.decoded;

const json = {
  disc: id, generated: new Date().toISOString(), totalBytes: total, duplicateEntries: { count: dupCount, bytes: dupBytes },
  now, before, understoodPct: +(100 * understood(now) / total).toFixed(3), understoodPctBefore: +(100 * understood(before) / total).toFixed(3),
  unknownChunkIds: Object.fromEntries([...unknownChunkIds].map(([k, v]) => [hex8(k), Math.round(v)])),
  items: all.sort((a, b) => b.bytes - a.bytes).map(i => ({ label: i.label, cat: i.cat, status: i.status, was: i.was, bytes: Math.round(i.bytes), files: i.files.size, count: i.count, tag: i.tag, reader: i.reader ?? null, es: i.es, en: i.en })),
};
mkdirSync(outDir(id), { recursive: true });
writeFileSync(`${outDir(id)}/coverage.json`, JSON.stringify(json, null, 1));

if (args.includes("--docs")) {
  for (const L of [0, 1] as const) {
    const t = (es: string, en: string) => (L ? en : es);
    const lines: string[] = [];
    const head = L ? HEADER_EN : HEADER_ES;
    lines.push(head.replace("{DATE}", json.generated.slice(0, 10)).replace("{ID}", id));
    lines.push(`## 1. ${t("Resumen", "Summary")}`, "");
    lines.push(`| ${t("Estado", "Status")} | ${t("Antes de la auditoría", "Before the audit")} | ${t("Ahora", "Now")} |`, "|---|---:|---:|");
    for (const s of Object.keys(ST) as Status[]) lines.push(`| ${ST[s][L]} | ${mb(before[s])} MB · ${pct(before[s])} | ${mb(now[s])} MB · ${pct(now[s])} |`);
    lines.push(`| **${t("Entendido (usado + descifrado)", "Understood (used + decoded)")}** | **${pct(understood(before))}** | **${pct(understood(now))}** |`);
    const nm = all.filter(i => i.cat !== "movies"), nmt = nm.reduce((x, i) => x + i.bytes, 0);
    const nmu = (k: "status" | "was") => nm.filter(i => i[k] === "used" || i[k] === "decoded").reduce((x, i) => x + i.bytes, 0);
    lines.push(`| ${t("Entendido sin contar las películas", "Understood excluding movies")} | ${pct(nmu("was"), nmt)} | **${pct(nmu("status"), nmt)}** |`);
    lines.push(`| ${t("Total del disco (bytes únicos)", "Disc total (unique bytes)")} | | ${mb(total)} MB |`, "");
    lines.push(t(`Entradas de ZDIR repetidas (misma posición): ${dupCount}, ${mb(dupBytes)} MB, no se cuentan dos veces.`,
      `Repeated ZDIR entries (same position): ${dupCount}, ${mb(dupBytes)} MB, not counted twice.`), "");
    lines.push(`## 2. ${t("Por categoría", "By category")}`, "");
    lines.push(`| ${t("Categoría", "Category")} | MB | ${ST.used[L]} | ${ST.decoded[L]} | ${ST.partial[L]} | ${ST.unknown[L]} | ${t("Entendido antes → ahora", "Understood before → now")} |`, "|---|---:|---:|---:|---:|---:|---:|");
    for (const c of Object.keys(CAT) as Cat[]) {
      const ci = all.filter(i => i.cat === c); const ct = ci.reduce((s, i) => s + i.bytes, 0); if (!ct) continue;
      const g = (s: Status, k: "status" | "was" = "status") => ci.filter(i => i[k] === s).reduce((a, i) => a + i.bytes, 0);
      lines.push(`| ${CAT[c][L]} | ${mb(ct)} | ${pct(g("used"), ct)} | ${pct(g("decoded"), ct)} | ${pct(g("partial"), ct)} | ${pct(g("unknown"), ct)} | ${pct(g("used", "was") + g("decoded", "was"), ct)} → **${pct(g("used") + g("decoded"), ct)}** |`);
    }
    lines.push("");
    let sec = 3;
    for (const c of Object.keys(CAT) as Cat[]) {
      const ci = all.filter(i => i.cat === c).sort((a, b) => b.bytes - a.bytes); if (!ci.length) continue;
      lines.push(`## ${sec++}. ${CAT[c][L]}`, "");
      lines.push(`| ${t("Qué", "What")} | MB | ${t("Archivos", "Files")} | ${t("Estado", "Status")} | ${t("Lector", "Reader")} | ${t("Nota", "Note")} |`, "|---|---:|---:|---|---|---|");
      for (const i of ci) lines.push(`| ${i.label.replace(/\|/g, "\\|")} | ${mb(i.bytes)} | ${i.files.size} | ${ST[i.status][L]}${i.was !== i.status ? ` (${t("antes", "was")}: ${ST[i.was][L]})` : ""} | ${i.reader ?? "—"} | ${i.tag} ${L ? i.en : i.es} |`);
      lines.push("");
    }
    lines.push(`## ${sec++}. ${t("Lo que falta, por tamaño", "What remains, by size")}`, "");
    lines.push(`| ${t("Qué", "What")} | MB | ${t("Estado", "Status")} | ${t("Qué creemos que es", "What we believe it is")} |`, "|---|---:|---|---|");
    for (const i of all.filter(i => i.status === "unknown" || i.status === "partial").sort((a, b) => b.bytes - a.bytes)) lines.push(`| ${i.label.replace(/\|/g, "\\|")} · ${CAT[i.cat][L]} | ${mb(i.bytes)} | ${ST[i.status][L]} | ${i.tag} ${L ? i.en : i.es} |`);
    lines.push("", L ? FOOTER_EN : FOOTER_ES);
    writeFileSync(`${repoRoot}docs/${L ? "en/21-coverage.md" : "es/21-cobertura.md"}`, lines.join("\n") + "\n");
  }
}
const nmAll = all.filter(i => i.cat !== "movies"), nmTot = nmAll.reduce((x, i) => x + i.bytes, 0);
const nmPct = (k: "status" | "was") => pct(nmAll.filter(i => i[k] === "used" || i[k] === "decoded").reduce((x, i) => x + i.bytes, 0), nmTot);
console.log(`Cobertura ${id}: sin películas ${nmPct("was")} → ${nmPct("status")}; entendido ${pct(understood(before))} → ${pct(understood(now))} de ${mb(total)} MB (usado ${pct(now.used)}, parcial ${pct(now.partial)}, desconocido ${pct(now.unknown)})`);
